/* Offline HTMX-compatible subset for AgentBox controls and event streams. */
(() => {
	"use strict";
	const terminalStates = new Set(["passed", "failed", "conflict", "killed", "merged", "discarded"]);
	const queryAll = (selector, root = document) => [...root.querySelectorAll(selector)];
	const emit = (name, detail) => document.dispatchEvent(new CustomEvent(name, { detail }));

	function swap(target, html, mode) {
		if (!target) return;
		const parsed = document.createElement("template");
		parsed.innerHTML = html;
		const first = parsed.content.firstElementChild;
		if (mode === "outerHTML" && first) target.replaceWith(first);
		else if (mode === "beforeend") target.insertAdjacentHTML("beforeend", html);
		else target.innerHTML = html;
		const inserted = mode === "outerHTML" ? first : target;
		emit("htmx:afterSwap", { target: inserted });
		process(inserted);
	}

	function swapOOB(html) {
		const parsed = document.createElement("template");
		parsed.innerHTML = html;
		const nodes = queryAll("[hx-swap-oob]", parsed.content);
		if (!nodes.length) return false;
		nodes.forEach(node => {
			const target = document.getElementById(node.id);
			const mode = node.getAttribute("hx-swap-oob") || "outerHTML";
			if (!target) return;
			if (mode === "innerHTML") target.innerHTML = node.innerHTML;
			else target.replaceWith(node);
			const inserted = mode === "innerHTML" ? target : node;
			emit("htmx:afterSwap", { target: inserted });
			process(inserted);
		});
		return true;
	}

	function request(event) {
		event.preventDefault();
		const source = event.currentTarget;
		const method = source.getAttribute("hx-get") ? "GET" : "POST";
		const url = source.getAttribute("hx-get") || source.getAttribute("hx-post");
		const target = document.querySelector(source.getAttribute("hx-target") || "#modal-root");
		const mode = source.getAttribute("hx-swap") || "innerHTML";
		const init = { method, headers: { "HX-Request": "true" } };
		if (method === "POST" && source.closest("form")) init.body = new FormData(source.closest("form"));
		source.setAttribute("aria-busy", "true");
		fetch(url, init)
			.then(response => response.text().then(html => ({ response, html })))
			.then(({ response, html }) => {
				if (!response.ok) throw Error(html || response.statusText);
				swap(target, html, mode);
			})
			.catch(error => {
				console.error("AgentBox request failed", error);
				emit("htmx:error", { target, error });
			})
			.finally(() => source.removeAttribute("aria-busy"));
	}

	function eventStatus(html, element) {
		const match = html.match(/data-task-status="([^"]+)"/);
		return match?.[1] || element.querySelector("[data-task-status]")?.dataset.taskStatus || "";
	}

	function connectStream(element) {
		if (element.dataset.sseBound) return;
		const url = element.getAttribute("sse-connect");
		if (!url || !window.EventSource) return;
		element.dataset.sseBound = "1";
		const source = new EventSource(url);
		["log", "status"].forEach(kind => source.addEventListener(kind, event => {
			if (!document.body.contains(element)) {
				source.close();
				return;
			}
			if (kind === "status") {
				const appliedOOB = swapOOB(event.data);
				if (!appliedOOB) {
					queryAll('[sse-swap="status"]', element).forEach(target => swap(target, event.data, "innerHTML"));
				}
				if (terminalStates.has(eventStatus(event.data, element))) source.close();
				return;
			}
			queryAll('[sse-swap="log"]', element).forEach(target => swap(target, event.data, "beforeend"));
		}));
		source.onerror = () => {
			if (!document.body.contains(element)) source.close();
		};
	}

	function process(root = document) {
		if (!root) return;
		const requests = [];
		if (root.matches?.("[hx-get],[hx-post]")) requests.push(root);
		requests.push(...queryAll("[hx-get],[hx-post]", root));
		requests.forEach(element => {
			if (element.dataset.hxBound) return;
			element.dataset.hxBound = "1";
			if ((element.getAttribute("hx-trigger") || "click").includes("load")) queueMicrotask(() => element.click());
			else element.addEventListener("click", request);
		});
		const streams = [];
		if (root.matches?.("[sse-connect]")) streams.push(root);
		streams.push(...queryAll("[sse-connect]", root));
		streams.forEach(connectStream);
	}

	window.htmx = {
		process,
		ajax: (method, url, options = {}) => fetch(url, { method })
			.then(response => response.text())
			.then(html => swap(document.querySelector(options.target), html, options.swap)),
	};
	document.addEventListener("DOMContentLoaded", () => process());
})();
